// Run with Electron on a disposable sample generated by workbench-sample.mjs.
const {app, BrowserWindow, ipcMain} = require('electron');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const {performance} = require('node:perf_hooks');
const {pathToFileURL} = require('node:url');
const [sample, stepArg, output] = process.argv.slice(2);
const root = fs.realpathSync(sample);
const evidenceRoot = path.resolve('.hermes');
const relative = path.relative(evidenceRoot,root);
if (!/^bench-[^/]+\/(2k|4k)$/.test(relative) || fs.existsSync(output)) {
  throw Error('Choose a dedicated .hermes/bench-*/2k or 4k sample and a new result file.');
}
const fixture = JSON.parse(fs.readFileSync(path.join(root,'.storyboard-flow/checkpoints/project.json'),'utf8'));
if (fixture.id !== 'studio-sample' || !Number.isInteger(Number(stepArg)) || Number(stepArg)<1 || Number(stepArg)>=fixture.shots.length)
  throw Error('Expected a generated sample and a navigation range inside its active boards.');
const steps = Number(stepArg);
const userData = fs.mkdtempSync(path.join(os.tmpdir(),'flow-profile-'));
const entry = path.resolve('dist-electron/main/flowEditorEntry.js');
process.argv = [process.execPath,entry,root,userData,'--workbench'];
const started = performance.now();
const delay = ms => new Promise(resolve => setTimeout(resolve,ms));
const report = {cpu:os.cpus()[0].model,ramGiB:os.totalmem()/2**30,steps,samples:[]};
async function waitFor(check, label) {
  const deadline = performance.now()+30000;
  do { if(await check()) return; await delay(8); } while(performance.now()<deadline);
  throw Error('Timeout: '+label);
}
// Observe the existing handler without changing its arguments, result or timing policy.
let stats={};globalThis.measure=async(name,fn)=>{const t=performance.now();try{return await fn()}finally{const item=stats[name]??={ms:0,n:0};item.ms+=performance.now()-t;item.n++}};
const checkpointMs = []; let saving=false;
const handle = ipcMain.handle.bind(ipcMain);
ipcMain.handle = (channel, listener) => {
  if (channel !== 'flow-editor:checkpoint') return handle(channel, listener);
  return handle(channel, async (...args) => {
    const start = performance.now();
    stats={};saving=true; try { return await listener(...args); }
    finally { saving=false; checkpointMs.push({ms:Math.round(performance.now()-start),stats}); }
  });
};
(async()=>{
  await import(pathToFileURL(entry).href); await app.whenReady();
  let win; await waitFor(()=>win=BrowserWindow.getAllWindows()[0],'window');
  const js=code=>win.webContents.executeJavaScript(code);
  const current=()=>js("document.querySelector('[data-current-shot]').dataset.currentShot");
  const settled=()=>js("document.querySelector('.wb-status')?.innerText.includes('所有修改已暂存')");
  const ready=()=>js("Array.from(document.querySelectorAll('.wb-viewer .image-stage > img')).filter(i=>i.complete&&i.naturalWidth===2048).length===3");
  await waitFor(settled,'initial checkpoint');await waitFor(ready,'layers');
  const arrow=()=>js("document.body.dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowRight',bubbles:true}))");
  const pixel=async(selector,f)=>js(`(()=>{const img=document.querySelector('${selector}');if(!img)return false;const c=document.createElement('canvas');c.width=c.height=1;const ctx=c.getContext('2d');ctx.drawImage(img,Math.floor(2048*${f}),576,1,1,0,0,1,1);const [r,g,b,a]=ctx.getImageData(0,0,1,1).data;return a>220&&r>160&&g<100&&b<150;})()`);
  async function stroke(f) {
    const r=await js("(()=>{const r=document.querySelector('.wb-viewer .image-stage').getBoundingClientRect();return [r.left,r.top,r.width,r.height]})()");
    const x=Math.round(r[0]+r[2]*f),y=Math.round(r[1]+r[3]/2);
    const mouse=(type,x)=>win.webContents.sendInputEvent({type,x,y,button:'left',clickCount:1});
    mouse('mouseMove',x-3);const start=performance.now();mouse('mouseDown',x-3);mouse('mouseMove',x+3);
    let visible=false; do {visible=await pixel('.wb-grid [data-live-mirror]',f);if(visible)break;await delay(8);}while(performance.now()-start<450);
    mouse('mouseUp',x+3);return {visible,ms:Math.round(performance.now()-start)};
  }
  if(path.basename(output)==='edit.json'){
    report.first=await stroke(.24);await waitFor(()=>saving,'first edit checkpoint in progress');
    report.second=await stroke(.50); report.duringSave=saving;
    const release=performance.now();await delay(100);report.rapid=await stroke(.62);
    report.rapidWhileSaving=saving;
    const ink='.wb-viewer .image-stage > img:nth-of-type(3)';
    async function history(label, expected){
      await js("Array.from(document.querySelectorAll('button')).find(b=>b.textContent==='"+label+"').click()");
      await waitFor(async()=>await ready() && await pixel(ink,.62)===expected && await pixel(ink,.50),label+' only the rapid stroke');
    }
    if(process.env.FLOW_CADENCE_HISTORY==='1'){
      await waitFor(async()=>await ready() && await pixel(ink,.62),'committed rapid stroke');
      await history('撤销',false);await history('重做',true);report.history=true;
    }
    report.arrows=[];while(await current()==='shot-0' && performance.now()-release<25000){
      const row={ms:Math.round(performance.now()-release),saving};await arrow();await delay(130);row.board=await current();report.arrows.push(row);await delay(170);
    }
    await waitFor(async()=>await current()==='shot-1','next board');await waitFor(ready,'next layers');
    report.third=await stroke(.76);await waitFor(async()=>await settled() && !saving && fs.existsSync(root+'/.storyboard-flow/checkpoints/versions/'+(fixture.revision+4+(report.history?2:0))+'.json') && !await js("!!document.querySelector('[data-live-mirror]')"),'third edit persisted');
  }else{
    const ink='.wb-viewer .image-stage > img:nth-of-type(3)';
    report.first=await pixel(ink,.24);report.second=await pixel(ink,.50);report.rapid=await pixel(ink,.62);
    await arrow();await waitFor(async()=>await current()==='shot-1','reopened second board');await waitFor(ready,'reopened layers');report.third=await pixel(ink,.76);
  }
  for(const key of ['first','second','rapid','third'])if((report[key]?.visible??report[key])!==true)throw Error('Missing stroke: '+key);
  report.checkpoints=checkpointMs;fs.writeFileSync(output,JSON.stringify(report));console.log(report);win.close();
})().catch(e=>{console.error(e,report);app.exit(1)});
